import{_ as s,c as n,a4 as e,o as p}from"./chunks/framework.BDeXF6e8.js";const m=JSON.parse('{"title":"nvm","description":"","frontmatter":{},"headers":[],"relativePath":"front/tools/包管理工具.md","filePath":"front/tools/包管理工具.md","lastUpdated":1747991870000}'),t={name:"front/tools/包管理工具.md"};function l(o,a,i,r,d,c){return p(),n("div",null,a[0]||(a[0]=[e(`<h1 id="nvm" tabindex="-1"><a href="https://github.com/coreybutler/nvm-windows" target="_blank" rel="noreferrer">nvm</a> <a class="header-anchor" href="#nvm" aria-label="Permalink to &quot;[nvm](https://github.com/coreybutler/nvm-windows)&quot;">​</a></h1><p>参考地址：<a href="https://blog.csdn.net/T_ianxin/article/details/131432914" target="_blank" rel="noreferrer">地址</a><a href="https://github.com/coreybutler/nvm-windows" target="_blank" rel="noreferrer">nvm</a> 全称为 node version manger，顾名思义就是管理 node 版本的一个工具，通过这个工具，我们可以在一台计算机上安装多个版本的 node，并且随时进行无缝的切换。</p><ol><li>卸载原本的 node.js</li></ol><p>如果之前有安装过 node.js，那么首先我们需要卸载掉之前的安装</p><ol start="2"><li>下载安装nvm</li></ol><p>链接:<a href="https://pan.baidu.com/s/1uoxlk8CVNHV2KTCwIGbQMQ?pwd=yi5m" target="_blank" rel="noreferrer">https://pan.baidu.com/s/1uoxlk8CVNHV2KTCwIGbQMQ?pwd=yi5m</a></p><p>提取码: yi5m</p><ol start="3"><li>修改nvm源</li></ol><p>如果直接用 nvm 命令下载 node 的话，因为源在国外，所以会导致下载失败，所以我们最好修改 nvm 的源</p><p>打开 nvm 的下载路径，如果你是一路 next 的，那么一般就在：C:\\Users\\你现在用的用户名\\AppData\\Roaming\\nvm</p><p>打开 setting.txt 文件，在末尾写入：</p><div class="language-vm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node_mirror: https://npm.taobao.org/mirrors/node/</span></span>
<span class="line"><span>npm_mirror: https://npm.taobao.org/mirrors/npm/</span></span></code></pre></div><ol start="4"><li>nvm常用命令</li></ol><h1 id="查看当前安装和使用的-node-版本" tabindex="-1">查看当前安装和使用的 node 版本 <a class="header-anchor" href="#查看当前安装和使用的-node-版本" aria-label="Permalink to &quot;查看当前安装和使用的 node 版本&quot;">​</a></h1><div class="language-vm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nvm list</span></span></code></pre></div><h1 id="安装某个-node-版本" tabindex="-1">安装某个 node 版本 <a class="header-anchor" href="#安装某个-node-版本" aria-label="Permalink to &quot;安装某个 node 版本&quot;">​</a></h1><div class="language-vm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nvm install 版本号</span></span></code></pre></div><h1 id="切换-node-版本" tabindex="-1">切换 node 版本 <a class="header-anchor" href="#切换-node-版本" aria-label="Permalink to &quot;切换 node 版本&quot;">​</a></h1><div class="language-vm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nvm use 版本号</span></span></code></pre></div><h1 id="设置默认版本" tabindex="-1">设置默认版本 <a class="header-anchor" href="#设置默认版本" aria-label="Permalink to &quot;设置默认版本&quot;">​</a></h1><div class="language-vm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nvm alias v12.22.12</span></span></code></pre></div><ol start="5"><li>配置 npm 源</li></ol><p>安装 node 之后，一般对应的 npm 也会被安装好，但是默认 npm 的源是指向 npm 官网的，这就导致我们在下载包的时候会很慢。</p><p>我们需要修改 npm 的源</p><div class="language-vm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm config set registry=https://registry.npm.taobao.org</span></span>
<span class="line"><span>npm config get registry</span></span></code></pre></div><h1 id="volta" tabindex="-1">volta <a class="header-anchor" href="#volta" aria-label="Permalink to &quot;volta&quot;">​</a></h1><p>Volta是一个项目级包管理工具，它可以帮助开发者在不同的项目中使用不同的版本的Node.js、npm、yarn。 自动管理全局安装包的路径，确保不同版本的Node.js不会冲突 官网：<a href="https://docs.volta.sh/guide/getting-started" target="_blank" rel="noreferrer">地址</a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>volta fetch 将工具缓存到本地机器以供离线使用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>volta install 设置工具的默认版本</span></span>
<span class="line"><span></span></span>
<span class="line"><span>volta uninstall 从工具链中卸载工具</span></span>
<span class="line"><span></span></span>
<span class="line"><span>volta pin 固定项目的运行时或包管理器</span></span>
<span class="line"><span></span></span>
<span class="line"><span>volta list 显示当前工具链</span></span>
<span class="line"><span></span></span>
<span class="line"><span>volta list all 显示所有工具链</span></span>
<span class="line"><span></span></span>
<span class="line"><span>volta completions 命令补全</span></span>
<span class="line"><span></span></span>
<span class="line"><span>volta which 查看 volta 安装的工具的目录</span></span>
<span class="line"><span></span></span>
<span class="line"><span>volta setup 为当前用户/shell 启用 volta</span></span>
<span class="line"><span></span></span>
<span class="line"><span>volta run 运行带有自定义Node、npm、pnpm和/或Yarn版本的命令</span></span>
<span class="line"><span></span></span>
<span class="line"><span>volta help 输出帮助信息</span></span></code></pre></div>`,28)]))}const v=s(t,[["render",l]]);export{m as __pageData,v as default};
